local extra = require('vim_practice.more_editing')
local ordered = {}
for _, category in ipairs(M.categories) do
  for _, exercise in ipairs(M.exercises) do
    if exercise.category == category.id then ordered[#ordered + 1] = exercise end
  end
  for _, exercise in ipairs(extra) do
    if exercise.category == category.id then ordered[#ordered + 1] = exercise end
  end
end
M.exercises = ordered
return M
